import pandas as pd
import numpy as np
from scipy import stats
from scipy.optimize import curve_fit

# Load all experiments
dfs = {}
for i, exp_id in enumerate([1, 3, 4, 5, 6]):
    try:
        df = pd.read_csv(eval(f"experiment_{exp_id}_csv"))
        dfs[exp_id] = df
        print(f"Exp {exp_id}: n={len(df)}, cols={list(df.columns)}")
    except Exception as e:
        print(f"Exp {exp_id} error: {e}")

# Check each experiment's dose level
for exp_id, df in dfs.items():
    print(f"\nExp {exp_id} - ChelatedMicronutrient levels:")
    if 'ChelatedMicronutrient' in df.columns:
        print(df['ChelatedMicronutrient'].describe())
    else:
        print("  No ChelatedMicronutrient column")
